const body = $items('Webhook (Refine)')[0].json;
const prior = $input.item.json;

if (!body.analysis_id) throw new Error('Missing analysis_id');
if (!prior || Object.keys(prior).length === 0) throw new Error('No stored data found for this analysis_id');

const zip = (body.zip || '').toString().trim();
const trade = (body.trade || '').toString().trim();

// Keep inputs consistent
prior.inputs = prior.inputs || {};
prior.inputs.zip = zip || prior.inputs.zip || '';
prior.inputs.trade = trade || prior.inputs.trade || '';

return [{ json: { analysis_id: body.analysis_id, prior, zip, trade } }];

